appConfig.mse:
fs:
  storage:
    type: rustfs
    rustfs:
      endpoint: {{S3_ENDPOINT}}
      access-key: {{S3_ACCESS_KEY}}
      secret-key: {{S3_SECRET_KEY}}
      bucket: mse-fs
      region: us-east-1
      path-style-access: true

im:
  enabled: true
  server:
    api-url: {{IM_API_URL}}
    ws-url: {{IM_WS_URL}}
    secret: {{IM_SECRET}}
    admin-user-id: imAdmin
  livekit:
    enabled: true
    url: {{IM_LIVEKIT_URL}}
    api-key: {{IM_LIVEKIT_API_KEY}}
    api-secret: {{IM_LIVEKIT_API_SECRET}}
